-- 20261105 rof2b port: vergalid - Vergalid Mines quests (17 tasks/56 objectives).
-- Source: github.com/nightstalker6669/EQEmu branch rof2-achievements,
--   extensions/rof2/achievements/content/vergalid (GPL-3.0), ported 2026-11-05.
-- Forward SQL files concatenated verbatim in install order; fail-closed
-- guards and session variables preserved. Reviewed-flag acceptance block
-- added here (upstream reconstruction defaults documented in the package's
-- provenance/ directory; see docs/rof2-zone-quests-attribution.md).
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
SET @vergalid_reviewed=1;
SET @vergalid_world_reviewed=1;
SET @vergalid_actor_profiles_reviewed=1;
SET @vergalid_activation_reviewed=1;
-- (reviewed flags accepted: @vergalid_reviewed, @vergalid_world_reviewed, @vergalid_actor_profiles_reviewed, @vergalid_activation_reviewed)

-- ---- vergalid/sql/020-journal-rewards.disabled.sql ----
-- OFFLINE disabled Vergalid journal/reward payload; world-acquisition dependencies remain separate.
-- MariaDB only. Review/protect writer state and backups before deliberate use. Never use --force.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_verg_tasks`;
CREATE TEMPORARY TABLE `_verg_tasks` LIKE `tasks`;
DROP TEMPORARY TABLE IF EXISTS `_verg_task_activities`;
CREATE TEMPORARY TABLE `_verg_task_activities` LIKE `task_activities`;
DROP TEMPORARY TABLE IF EXISTS `_verg_achievement_criteria`;
