DROP TEMPORARY TABLE IF EXISTS `_verg_guard`;
CREATE TEMPORARY TABLE `_verg_guard`(ok TINYINT NOT NULL CHECK(ok=1))ENGINE=InnoDB;
START TRANSACTION;
SET @vergalid_ok=COALESCE(@vergalid_reviewed,0)=1 AND
((SELECT COUNT(*)FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN(CONVERT(0x7461736b73 USING utf8mb4),CONVERT(0x7461736b5f61637469766974696573 USING utf8mb4),CONVERT(0x616368696576656d656e745f6372697465726961 USING utf8mb4),CONVERT(0x7265776172645f73657473 USING utf8mb4),CONVERT(0x7265776172645f736f7572636573 USING utf8mb4),CONVERT(0x72657761726473 USING utf8mb4),CONVERT(0x7265776172645f6f7074696f6e73 USING utf8mb4),CONVERT(0x7265776172645f6f7074696f6e5f656e7472696573 USING utf8mb4)) AND ENGINE='InnoDB')=8)
 AND (NOT EXISTS(SELECT 1 FROM `tasks` a WHERE (a.id IN(3040801,3040802,3040803,3040804,3040805,3040806,3040807,3040808,3040809,3040810,3040811,3040812,3040813,3040814,3040815,3040816,3040817)) AND NOT EXISTS(SELECT 1 FROM `_verg_tasks` e WHERE a.`id`<=>e.`id` AND a.`type`<=>e.`type` AND a.`duration`<=>e.`duration` AND a.`title`<=>e.`title` AND a.`description`<=>e.`description` AND a.`reward_text`<=>e.`reward_text` AND a.`reward_id_list`<=>e.`reward_id_list` AND a.`cash_reward`<=>e.`cash_reward` AND a.`exp_reward`<=>e.`exp_reward` AND a.`reward_method`<=>e.`reward_method` AND a.`min_level`<=>e.`min_level` AND a.`max_level`<=>e.`max_level` AND a.`level_spread`<=>e.`level_spread` AND a.`min_players`<=>e.`min_players` AND a.`max_players`<=>e.`max_players` AND a.`repeatable`<=>e.`repeatable` AND a.`faction_reward`<=>e.`faction_reward` AND a.`faction_amount`<=>e.`faction_amount` AND a.enabled IN(0,1))))
 AND (NOT EXISTS(SELECT 1 FROM `task_activities` a WHERE (a.taskid IN(3040801,3040802,3040803,3040804,3040805,3040806,3040807,3040808,3040809,3040810,3040811,3040812,3040813,3040814,3040815,3040816,3040817)) AND NOT EXISTS(SELECT 1 FROM `_verg_task_activities` e WHERE a.`taskid`<=>e.`taskid` AND a.`activityid`<=>e.`activityid` AND a.`req_activity_id`<=>e.`req_activity_id` AND a.`step`<=>e.`step` AND a.`activitytype`<=>e.`activitytype` AND a.`target_name`<=>e.`target_name` AND a.`goalmethod`<=>e.`goalmethod` AND a.`goalcount`<=>e.`goalcount` AND a.`description_override`<=>e.`description_override` AND a.`npc_match_list`<=>e.`npc_match_list` AND a.`item_id_list`<=>e.`item_id_list` AND a.`zones`<=>e.`zones` AND a.`spell_list`<=>e.`spell_list` AND a.`optional`<=>e.`optional` AND a.`min_x`<=>e.`min_x` AND a.`max_x`<=>e.`max_x` AND a.`min_y`<=>e.`min_y` AND a.`max_y`<=>e.`max_y` AND a.`min_z`<=>e.`min_z` AND a.`max_z`<=>e.`max_z`)))
