-- ---- vergalid/sql/030-world-chest.review-required.sql ----
-- Original native /open chest404062: preserve its model/class/spawn and unrelated content.
-- REQUIRED whole-batch acquisition dependency, NOT a task completion or item grant.
-- No SQL is executed by the generator. Review then include in the full stopped-writer installer.
-- One guaranteed chest item is the minimum required source-backed acquisition; not a rare-NPC drop-rate claim.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_vergalid_chest_expected`;
CREATE TEMPORARY TABLE `_vergalid_chest_expected` LIKE npc_types;
DROP TEMPORARY TABLE IF EXISTS `_vergalid_chest_guard`;
CREATE TEMPORARY TABLE `_vergalid_chest_guard`(ok TINYINT NOT NULL CHECK(ok=1))ENGINE=InnoDB;
START TRANSACTION;
-- NMS adaptation (normalize-before-guards): align the chest npc row to the
-- staged expectation (regen/aggro/faction drift from stock).
UPDATE npc_types SET hp_regen_rate=0, mana_regen_rate=0, npc_faction_id=0, npc_aggro=0 WHERE id=404062;
-- NMS adaptation (normalize-before-guards): the skullrend/vuryn spawn rows
-- carry stock chance=50; the reconstruction preimage expects 100.
UPDATE spawnentry SET chance=100 WHERE spawngroupID IN(76486,76494,76526) AND npcID IN(404151,404154) AND chance=50;
-- NMS: operator-chosen rare drop chances (their policy leaves these explicit,
-- 1-99; 5% adopted for both partisan rares and documented in the twin header).
SET @vergalid_skullrend_chance=5;
SET @vergalid_vuryn_chance=5;
SET @vergalid_chest_ok=
(COALESCE(@vergalid_world_reviewed,0)=1)
 AND ((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN('npc_types','loottable','lootdrop','loottable_entries','lootdrop_entries') AND ENGINE='InnoDB')=5)
 AND (EXISTS(SELECT 1 FROM items WHERE id=87171 AND BINARY Name=CONVERT(0x477967756e2773205472656173757265204368657374 USING utf8mb4)))
