DROP TEMPORARY TABLE IF EXISTS `_verga_lootdrop_entries`;
CREATE TEMPORARY TABLE `_verga_lootdrop_entries` LIKE `lootdrop_entries`;
DROP TEMPORARY TABLE IF EXISTS `_verga_original_spawn2`;
CREATE TEMPORARY TABLE `_verga_original_spawn2` LIKE `spawn2`;
DROP TEMPORARY TABLE IF EXISTS `_verga_original_spawngroup`;
CREATE TEMPORARY TABLE `_verga_original_spawngroup` LIKE `spawngroup`;
