-- ---- vergalid/sql/090-enable-whole-batch.sql ----
-- Whole-batch activation only: preceding journal/chest/actor success latches must share this transaction.
-- Disabled/unknown minimum-level sentinel255 is deliberately rejected.
-- Matching enabled Lua payload and separately reviewed world policy are required by install.py.
DROP TEMPORARY TABLE IF EXISTS `_vergalid_activation_guard`;
CREATE TEMPORARY TABLE `_vergalid_activation_guard`(ok TINYINT NOT NULL CHECK(ok=1))ENGINE=InnoDB;
START TRANSACTION;
SET @vergalid_activation_ok=
(COALESCE(@vergalid_activation_reviewed,0)=1)
 AND (COALESCE(@vergalid_ok,0)=1)
 AND (COALESCE(@vergalid_chest_ok,0)=1)
 AND (COALESCE(@vergalid_actor_world_ok,0)=1)
 AND ((SELECT COUNT(*)FROM tasks WHERE id IN(3040801,3040802,3040803,3040804,3040805,3040806,3040807,3040808,3040809,3040810,3040811,3040812,3040813,3040814,3040815,3040816,3040817) AND min_level BETWEEN 1 AND 100)=17)
 AND ((SELECT COUNT(*)FROM achievements WHERE id IN(500080200,500080300,500080400,500080500))=4)
 AND ((SELECT COUNT(*)FROM npc_types WHERE id BETWEEN 404900 AND 404906)=7)
 AND (EXISTS(SELECT 1 FROM npc_types WHERE id=404062 AND loottable_id=3040807))
 AND ((SELECT COUNT(*)FROM `tasks` WHERE id IN(3040801,3040802,3040803,3040804,3040805,3040806,3040807,3040808,3040809,3040810,3040811,3040812,3040813,3040814,3040815,3040816,3040817))=17)
 AND ((SELECT COUNT(*)FROM `task_activities` WHERE taskid IN(3040801,3040802,3040803,3040804,3040805,3040806,3040807,3040808,3040809,3040810,3040811,3040812,3040813,3040814,3040815,3040816,3040817))=56)
 AND ((SELECT COUNT(*)FROM `achievement_criteria` WHERE component_type=1 AND component_id BETWEEN 50218 AND 50234)=17)
 AND ((SELECT COUNT(*)FROM `reward_sets` WHERE reward_set_id IN(3040803,3040813,3040891,3040892,3040893,3040894))=6)
 AND ((SELECT COUNT(*)FROM `reward_sources` WHERE reward_set_id IN(3040803,3040813,3040891,3040892,3040893,3040894))=6)
 AND ((SELECT COUNT(*)FROM `rewards` WHERE reward_id IN(304080310,304080320,304081310,304081320,304089110,304089120,304089130,304089140,304089210,304089220,304089230,304089240,304089310,304089320,304089410,304089411,304089420,304089421))=18)
 AND ((SELECT COUNT(*)FROM `reward_options` WHERE reward_set_id IN(3040803,3040813,3040891,3040892,3040893,3040894))=16)
 AND ((SELECT COUNT(*)FROM `reward_option_entries` WHERE reward_set_id IN(3040803,3040813,3040891,3040892,3040893,3040894))=18);
UPDATE `tasks` SET enabled=1 WHERE @vergalid_activation_ok=1 AND (id IN(3040801,3040802,3040803,3040804,3040805,3040806,3040807,3040808,3040809,3040810,3040811,3040812,3040813,3040814,3040815,3040816,3040817));
UPDATE `achievement_criteria` SET enabled=1 WHERE @vergalid_activation_ok=1 AND (component_type=1 AND component_id BETWEEN 50218 AND 50234);
UPDATE `reward_sets` SET enabled=1 WHERE @vergalid_activation_ok=1 AND (reward_set_id IN(3040803,3040813,3040891,3040892,3040893,3040894));
UPDATE `reward_sources` SET enabled=1 WHERE @vergalid_activation_ok=1 AND (reward_set_id IN(3040803,3040813,3040891,3040892,3040893,3040894));
UPDATE `rewards` SET enabled=1 WHERE @vergalid_activation_ok=1 AND (reward_id IN(304080310,304080320,304081310,304081320,304089110,304089120,304089130,304089140,304089210,304089220,304089230,304089240,304089310,304089320,304089410,304089411,304089420,304089421));
UPDATE `reward_options` SET enabled=1 WHERE @vergalid_activation_ok=1 AND (reward_set_id IN(3040803,3040813,3040891,3040892,3040893,3040894));
UPDATE achievements SET enabled=1 WHERE @vergalid_activation_ok=1 AND id IN(500080200,500080300,500080400,500080500);
COMMIT;
SET @vergalid_activation_ok=NULL;
