INSERT INTO `tasks`(`id`,`type`,`duration`,`title`,`description`,`reward_text`,`reward_id_list`,`cash_reward`,`exp_reward`,`reward_method`,`min_level`,`max_level`,`level_spread`,`min_players`,`max_players`,`repeatable`,`faction_reward`,`faction_amount`,`enabled`) SELECT e.`id`,e.`type`,e.`duration`,e.`title`,e.`description`,e.`reward_text`,e.`reward_id_list`,e.`cash_reward`,e.`exp_reward`,e.`reward_method`,e.`min_level`,e.`max_level`,e.`level_spread`,e.`min_players`,e.`max_players`,e.`repeatable`,e.`faction_reward`,e.`faction_amount`,e.`enabled` FROM `_verg_tasks` e WHERE @vergalid_ok=1 AND NOT EXISTS(SELECT 1 FROM `tasks` a WHERE a.`id`<=>e.`id`);
INSERT INTO `task_activities`(`taskid`,`activityid`,`req_activity_id`,`step`,`activitytype`,`target_name`,`goalmethod`,`goalcount`,`description_override`,`npc_match_list`,`item_id_list`,`zones`,`spell_list`,`optional`,`min_x`,`max_x`,`min_y`,`max_y`,`min_z`,`max_z`) SELECT e.`taskid`,e.`activityid`,e.`req_activity_id`,e.`step`,e.`activitytype`,e.`target_name`,e.`goalmethod`,e.`goalcount`,e.`description_override`,e.`npc_match_list`,e.`item_id_list`,e.`zones`,e.`spell_list`,e.`optional`,e.`min_x`,e.`max_x`,e.`min_y`,e.`max_y`,e.`min_z`,e.`max_z` FROM `_verg_task_activities` e WHERE @vergalid_ok=1 AND NOT EXISTS(SELECT 1 FROM `task_activities` a WHERE a.`taskid`<=>e.`taskid` AND a.`activityid`<=>e.`activityid`);
INSERT INTO `achievement_criteria`(`achievement_id`,`component_type`,`component_sequence`,`component_id`,`event_type`,`progress_mode`,`behavior`,`target_id`,`target_id2`,`target_value`,`required_count`,`enabled`) SELECT e.`achievement_id`,e.`component_type`,e.`component_sequence`,e.`component_id`,e.`event_type`,e.`progress_mode`,e.`behavior`,e.`target_id`,e.`target_id2`,e.`target_value`,e.`required_count`,e.`enabled` FROM `_verg_achievement_criteria` e WHERE @vergalid_ok=1 AND NOT EXISTS(SELECT 1 FROM `achievement_criteria` a WHERE a.`achievement_id`<=>e.`achievement_id` AND a.`component_type`<=>e.`component_type` AND a.`component_id`<=>e.`component_id`);
INSERT INTO `reward_sets`(`reward_set_id`,`title`,`enabled`) SELECT e.`reward_set_id`,e.`title`,e.`enabled` FROM `_verg_reward_sets` e WHERE @vergalid_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_sets` a WHERE a.`reward_set_id`<=>e.`reward_set_id`);
INSERT INTO `reward_sources`(`source_type`,`source_id`,`reward_set_id`,`enabled`) SELECT e.`source_type`,e.`source_id`,e.`reward_set_id`,e.`enabled` FROM `_verg_reward_sources` e WHERE @vergalid_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_sources` a WHERE a.`source_type`<=>e.`source_type` AND a.`source_id`<=>e.`source_id`);
INSERT INTO `rewards`(`reward_id`,`reward_type`,`reward_data_id`,`amount`,`description`,`enabled`) SELECT e.`reward_id`,e.`reward_type`,e.`reward_data_id`,e.`amount`,e.`description`,e.`enabled` FROM `_verg_rewards` e WHERE @vergalid_ok=1 AND NOT EXISTS(SELECT 1 FROM `rewards` a WHERE a.`reward_id`<=>e.`reward_id`);
INSERT INTO `reward_options`(`reward_set_id`,`option_id`,`sequence`,`label`,`common_to_all`,`flags`,`enabled`,`class_mask`) SELECT e.`reward_set_id`,e.`option_id`,e.`sequence`,e.`label`,e.`common_to_all`,e.`flags`,e.`enabled`,e.`class_mask` FROM `_verg_reward_options` e WHERE @vergalid_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_options` a WHERE a.`reward_set_id`<=>e.`reward_set_id` AND a.`option_id`<=>e.`option_id`);
INSERT INTO `reward_option_entries`(`reward_set_id`,`option_id`,`sequence`,`reward_id`) SELECT e.`reward_set_id`,e.`option_id`,e.`sequence`,e.`reward_id` FROM `_verg_reward_option_entries` e WHERE @vergalid_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_option_entries` a WHERE a.`reward_set_id`<=>e.`reward_set_id` AND a.`option_id`<=>e.`option_id` AND a.`sequence`<=>e.`sequence`);
